{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "The closest structural analogue, a hydroxyethylamine peptidomimetic with a benzyl group and multiple amides, was below the detection limit in mouse brain after i.v. dosing despite ~1.3 µM plasma exposure and was identified as a P-gp substrate, directly demonstrating poor CNS access for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "In situ mouse brain perfusion showed an extremely low unidirectional transfer constant (Kin 8.2 × 10^-5 mL/s/g) for a large polar inhibitor, confirming poor BBB permeation independent of plasma exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "A brain/blood concentration ratio of 0.02 in mice for a related heteroaromatic inhibitor indicates negligible brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Quantitative whole-body autoradiography after i.v. administration of a radiolabeled peptide-like molecule detected no brain or spinal cord radioactivity, showing that polar peptide-like molecules can be effectively excluded from the CNS.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "A brain-to-plasma ratio of 0.1 or lower in rats for another high-transfer analogue reinforces the pattern of poor CNS exposure among structurally relevant molecules.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues demonstrate poor brain penetration, efflux liability, or peripheral restriction; the query is a large, highly functionalized peptidomimetic with multiple H-bond donors/acceptors and a pyridine, so meaningful CNS access is unlikely.",
  "evidence_gaps": [
    "No direct brain, CSF, or unbound brain-to-plasma measurement exists for the query molecule itself.",
    "The query's P-gp/BCRP transporter status has not been experimentally determined.",
    "No human CNS exposure data are available for the query or exact structural analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

